<script setup lang="ts">
import { ArrowLeft, Bot, Check, ChevronLeft, Clock3, Folder, Plus, Send, ShieldAlert, Wrench, X } from 'lucide-vue-next'
import { computed, nextTick, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { api } from '@/api/client'
import MarkdownContent from '@/components/MarkdownContent.vue'
import { extractSseEvents } from '@/runtime/sse'
import type { Agent, Message, ModelConfig, RunEvent, Session, Skill, Tool } from '@/types'
const route=useRoute(),agent=ref<Agent|null>(null),model=ref<ModelConfig|null>(null),tools=ref<Tool[]>([]),skills=ref<Skill[]>([]),sessions=ref<Session[]>([]),session=ref<Session|null>(null),messages=ref<Message[]>([]),events=ref<RunEvent[]>([]),draft=ref(''),running=ref(false),error=ref(''),timeline=ref<HTMLElement|null>(null),mobileSessions=ref(false),mobileContext=ref(false)
const boundTools=computed(()=>tools.value.filter(t=>agent.value?.tool_ids.includes(t.id))),boundSkills=computed(()=>skills.value.filter(s=>agent.value?.skill_ids.includes(s.id)))
async function load(){try{const id=route.params.id as string;const [loadedAgent,loadedTools,loadedSkills]=await Promise.all([api<Agent>(`/api/agents/${id}`),api<Tool[]>('/api/tools'),api<Skill[]>('/api/skills')]);agent.value=loadedAgent;tools.value=loadedTools;skills.value=loadedSkills;model.value=await api<ModelConfig>(`/api/models/${loadedAgent.model_id}`);sessions.value=(await api<Session[]>('/api/sessions')).filter(s=>s.agent_id===id);if(sessions.value[0])await selectSession(sessions.value[0])}catch(e){error.value=(e as Error).message}}
async function createSession(){if(!agent.value)return;const created=await api<Session>('/api/sessions',{method:'POST',body:JSON.stringify({agent_id:agent.value.id,title:'新会话'})});session.value=created;sessions.value.unshift(created);messages.value=[];events.value=[];mobileSessions.value=false}
async function selectSession(item:Session){session.value=item;messages.value=await api(`/api/sessions/${item.id}/messages`);events.value=[];mobileSessions.value=false}
async function approve(id:string,allowed:boolean){try{await api(`/api/approvals/${id}`,{method:'POST',body:JSON.stringify({allowed})})}catch(e){error.value=(e as Error).message}}
async function send(){if(!draft.value.trim()||running.value)return;if(!session.value)await createSession();if(!session.value)return;const content=draft.value.trim();draft.value='';messages.value.push({id:crypto.randomUUID(),role:'user',content,created_at:new Date().toISOString()});events.value=[];running.value=true;error.value='';await nextTick();timeline.value?.scrollTo({top:timeline.value.scrollHeight});try{const response=await fetch(`/api/sessions/${session.value.id}/runs`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content})});if(!response.ok||!response.body)throw new Error('无法启动智能体运行');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const parsed=extractSseEvents(buffer);buffer=parsed.rest;for(const event of parsed.events){events.value.push(event);if(event.type==='message.delta'){const last=messages.value[messages.value.length-1];if(last?.role==='assistant')last.content+=String(event.data.content);else messages.value.push({id:crypto.randomUUID(),role:'assistant',content:String(event.data.content),created_at:event.timestamp})}if(event.type==='run.failed')error.value=String(event.data.message||'运行失败');await nextTick();timeline.value?.scrollTo({top:timeline.value.scrollHeight,behavior:'smooth'})}}}catch(e){error.value=(e as Error).message}finally{running.value=false}}
function toolName(id:unknown){return tools.value.find(t=>t.id===id)?.name||String(id)}
onMounted(load)
</script>
<template><div class="run-heading"><div><RouterLink class="back-link" to="/agents"><ArrowLeft :size="13"/>智能体</RouterLink><h1>{{agent?.name||'加载中'}}</h1></div><div class="run-actions"><button class="button button--secondary mobile-only" @click="mobileSessions=true">会话</button><button class="button button--secondary mobile-only" @click="mobileContext=true">上下文</button><button class="button button--lime" @click="createSession"><Plus :size="14"/>新会话</button></div></div><div class="run-shell"><aside class="session-pane" :class="{open:mobileSessions}"><header><span>会话</span><button class="icon-button mobile-only" title="关闭" @click="mobileSessions=false"><X :size="15"/></button></header><button v-for="item in sessions" :key="item.id" class="session-item" :class="{active:session?.id===item.id}" @click="selectSession(item)"><span>{{item.title}}</span><small>{{new Date(item.updated_at).toLocaleString('zh-CN')}}</small></button><div v-if="!sessions.length" class="pane-empty">还没有会话</div></aside><section class="conversation"><div ref="timeline" class="timeline"><div v-if="!messages.length&&!events.length" class="welcome"><span><Bot :size="22"/></span><h2>开始一次本地任务</h2><p>消息将使用当前模型、提示词、工具和技能运行。</p></div><article v-for="message in messages" :key="message.id" class="message" :class="message.role"><div class="message-role">{{message.role==='user'?'你':'智能体'}}</div><MarkdownContent v-if="message.role==='assistant'" :content="message.content"/><div v-else class="message-content">{{message.content}}</div></article><template v-for="event in events" :key="`${event.sequence}-${event.type}`"><article v-if="event.type==='tool.requested'" class="event-card tool"><header><Wrench :size="14"/><b>请求工具：{{toolName(event.data.name)}}</b></header><pre>{{JSON.stringify(event.data.arguments,null,2)}}</pre></article><article v-if="event.type==='approval.required'" class="event-card approval"><header><ShieldAlert :size="15"/><b>需要你的审批</b></header><p>{{toolName(event.data.name)}} 将在当前工作目录执行以下操作：</p><pre>{{JSON.stringify(event.data.arguments,null,2)}}</pre><div class="actions"><button class="button button--danger" @click="approve(String(event.data.approval_id),false)"><X :size="13"/>拒绝</button><button class="button" @click="approve(String(event.data.approval_id),true)"><Check :size="13"/>允许一次</button></div></article><article v-if="event.type==='tool.completed'" class="event-card result"><header><Check :size="14"/><b>{{toolName(event.data.name)}} 已完成</b></header></article></template><div v-if="running" class="thinking"><span/><span/><span/>智能体正在处理</div><div v-if="error" class="error">{{error}}</div></div><form class="composer" @submit.prevent="send"><textarea v-model="draft" rows="1" placeholder="输入任务，Enter 发送，Shift + Enter 换行" @keydown.enter.exact.prevent="send"/><button class="button" :disabled="running||!draft.trim()" title="发送"><Send :size="16"/><span>发送</span></button></form></section><aside class="context-pane" :class="{open:mobileContext}"><header><span>运行上下文</span><button class="icon-button mobile-only" title="关闭" @click="mobileContext=false"><X :size="15"/></button></header><div class="context-block"><label>模型</label><b>{{model?.name||'未配置'}}</b><small>{{model?.model}}</small></div><div class="context-block"><label>工作目录</label><p><Folder :size="13"/>{{agent?.work_directory}}</p></div><div class="context-block"><label>工具</label><span v-for="tool in boundTools" :key="tool.id" class="context-chip">{{tool.name}}</span><small v-if="!boundTools.length">未绑定工具</small></div><div class="context-block"><label>技能</label><span v-for="skill in boundSkills" :key="skill.id" class="context-chip">{{skill.name}}</span><small v-if="!boundSkills.length">未绑定技能</small></div></aside></div></template>
<style scoped>.run-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:13px}.run-heading h1{font-size:19px;margin:4px 0 0}.back-link{display:inline-flex;align-items:center;gap:5px;color:var(--muted);font-size:10px;text-decoration:none}.run-actions{display:flex;gap:7px}.run-shell{height:calc(100vh - 130px);min-height:560px;display:grid;grid-template-columns:220px minmax(380px,1fr) 250px;border:1px solid var(--line);background:white;border-radius:var(--radius);overflow:hidden}.session-pane,.context-pane{background:#f0f2ef}.session-pane{border-right:1px solid var(--line)}.context-pane{border-left:1px solid var(--line)}.session-pane>header,.context-pane>header{height:45px;padding:0 13px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);font-size:11px;font-weight:700}.session-item{width:100%;min-height:54px;padding:9px 12px;text-align:left;border:0;border-bottom:1px solid var(--line);background:transparent;cursor:pointer}.session-item:hover,.session-item.active{background:white}.session-item span,.session-item small{display:block}.session-item span{font-size:11px;font-weight:700}.session-item small{margin-top:4px;color:var(--muted);font-size:8px}.pane-empty{padding:24px 13px;color:var(--muted);text-align:center;font-size:10px}.conversation{min-width:0;display:grid;grid-template-rows:1fr auto;overflow:hidden}.timeline{overflow-y:auto;padding:24px}.welcome{min-height:100%;display:grid;place-content:center;text-align:center;color:var(--muted)}.welcome>span{width:45px;height:45px;display:grid;place-items:center;margin:0 auto;background:#e4f2cc;color:#3c5518}.welcome h2{color:var(--ink);font-size:14px;margin:12px 0 4px}.welcome p{font-size:10px;margin:0}.message{max-width:78%;margin-bottom:17px}.message.user{margin-left:auto}.message-role{font-size:9px;font-weight:700;color:var(--muted);margin-bottom:5px}.message.user .message-role{text-align:right}.message-content{white-space:pre-wrap;padding:11px 13px;background:#edf0ed;border-radius:5px;font-size:12px;line-height:1.7}.message.user .message-content{background:#202622;color:white}.event-card{max-width:88%;margin:0 0 12px;border:1px solid var(--line);border-left:3px solid var(--mint);background:#f7faf7;padding:11px}.event-card.approval{border-left-color:var(--amber);background:#fff9ec}.event-card header{display:flex;align-items:center;gap:7px;font-size:11px}.event-card p{font-size:10px;color:var(--muted)}.event-card pre{margin:9px 0;max-height:140px;font-size:9px}.event-card .actions{justify-content:flex-end}.thinking{display:flex;align-items:center;gap:4px;color:var(--muted);font-size:10px}.thinking span{width:5px;height:5px;border-radius:50%;background:var(--mint);animation:pulse 1s infinite}.thinking span:nth-child(2){animation-delay:.15s}.thinking span:nth-child(3){animation-delay:.3s;margin-right:4px}@keyframes pulse{50%{opacity:.25}}.composer{display:grid;grid-template-columns:1fr auto;gap:8px;padding:12px;border-top:1px solid var(--line);background:#fafbf9}.composer textarea{min-height:40px;max-height:120px;resize:none;border:1px solid var(--line-dark);border-radius:var(--radius);padding:10px 11px;font-size:12px}.context-block{padding:14px;border-bottom:1px solid var(--line)}.context-block label{display:block;margin-bottom:8px;color:var(--muted);font-size:9px;font-weight:700}.context-block b,.context-block small{display:block}.context-block b{font-size:11px}.context-block small{margin-top:3px;color:var(--muted);font:8px/1.5 ui-monospace,monospace}.context-block p{display:flex;gap:6px;align-items:flex-start;word-break:break-all;margin:0;color:#4e5b53;font:8px/1.55 ui-monospace,monospace}.context-chip{display:inline-block;margin:0 4px 4px 0;padding:4px 6px;background:white;border:1px solid var(--line);font-size:9px}.mobile-only{display:none!important}@media(max-width:1050px){.run-shell{grid-template-columns:200px minmax(360px,1fr)}.context-pane{display:none}}@media(max-width:760px){.mobile-only{display:inline-flex!important}.run-shell{height:calc(100vh - 170px);grid-template-columns:1fr;min-height:500px}.session-pane,.context-pane{display:block;position:fixed;top:0;bottom:0;z-index:50;width:min(300px,85vw);transition:transform .2s}.session-pane{left:0;transform:translateX(-100%)}.context-pane{right:0;transform:translateX(100%)}.session-pane.open,.context-pane.open{transform:translateX(0)}.message{max-width:92%}.timeline{padding:15px}.composer .button span{display:none}}</style>
